            ["OrpheusMusicProgress02"] = {
                {
                    ["Text"] = "Zagreus, I heard your recent lyre-playing from your bedchambers. Let no one lead you to believe it's not a reassuring start.";
                    ["Cue"] = "/VO/Orpheus_0217";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Oh, come now, mate, I'm terrible and you know it. You pulling one over on me as payback?";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_1044";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                };
                {
                    ["Text"] = "I'm being serious, my friend. It is a challenging pursuit requiring a dedicated state of mind. The progress shall come. You shall discover what I mean.";
                    ["Cue"] = "/VO/Orpheus_0218";
                    ["PreLineAnim"] = "OrpheusFidget";
                };
                ["RequiredCosmetics"] = {
                    "HouseLyre01";
                };
                ["RequiredTextLines"] = {
                    "OrpheusMusicProgress01";
                };
                ["RequiredMinItemInteractions"] = {
                    ["HouseLyre01"] = 60;
                };
                ["PlayOnce"] = true;
                ["EndCue"] = "/VO/ZagreusHome_1045";
                ["EndWait"] = 0.4;
                ["UseableOffSource"] = true;
                ["RequiredFalseTextLinesLastRun"] = {
                    "OrpheusMusicProgress01";
                };
                ["Priority"] = true;
                ["Name"] = "OrpheusMusicProgress02";
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusMusicProgress01"] = {
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Hey Orpheus! I got myself a lyre much like yours, except I'm absolutely miserable when I try to play! Got any advice?";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_1042";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                };
                {
                    ["Text"] = "Oh, why, that's splendid, Zagreus. And I can certainly show you a thing or two. First, the proper posture is important, here...";
                    ["Cue"] = "/VO/Orpheus_0215";
                    ["PostLineThreadedFunctionName"] = "MusicPracticePresentation";
                };
                {
                    ["FadeInSound"] = "/Leftovers/Menu Sounds/EmoteExcitement";
                    ["InterSceneWaitTime"] = 0.3;
                    ["Text"] = "...now remember to practice the plucking technique which I taught you, and mind your off-hand constantly. And, above all, continue practicing! The joyfulness is in the practicing itself.";
                    ["PreLineWait"] = 0.1;
                    ["FullFadeTime"] = 7;
                    ["Cue"] = "/VO/Orpheus_0216";
                    ["FadeOutTime"] = 0.5;
                    ["FadeInTime"] = 1;
                };
                ["RequiredCosmetics"] = {
                    "HouseLyre01";
                };
                ["RequiredMinItemInteractions"] = {
                    ["HouseLyre01"] = 10;
                };
                ["EndCue"] = "/VO/ZagreusHome_1043";
                ["EndWait"] = 0.6;
                ["UseableOffSource"] = true;
                ["PlayOnce"] = true;
                ["Priority"] = true;
                ["Name"] = "OrpheusMusicProgress01";
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusWithAchilles02"] = {
                {
                    ["Text"] = "...Do you miss it, yourself, Lord Achilles, sir? The freshness of the air. The need to have meals several times a day, and such.";
                    ["Cue"] = "/VO/Orpheus_0225";
                    ["PreLineWait"] = 0.3;
                };
                {
                    ["Portrait"] = "Portrait_MaleGhost_Default_01";
                    ["Cue"] = "/VO/Achilles_0128";
                    ["Speaker"] = "NPC_Achilles_01";
                    ["Text"] = "I scarce remember it, my friend. Although your songs do stir up memories, sometimes. I'm used to things the way they are, I think. But you, not so much?";
                };
                {
                    ["Text"] = "Oh, on the contrary, sir, I am profoundly satisfied. We are most fortunate to have employment even after death. Imagine, merely resting for eternity, when you could work!";
                    ["Cue"] = "/VO/Orpheus_0226";
                    ["PreLineAnim"] = "OrpheusFidget";
                    ["PreLineWait"] = 0.3;
                };
                ["GiftableOffSource"] = true;
                ["Name"] = "OrpheusWithAchilles02";
                ["RequiredAnyOtherTextLines"] = {
                    "OrpheusSingsAgain03";
                    "OrpheusSingsAgain03_B";
                };
                ["TeleportOffsetX"] = 40;
                ["UseText"] = "UseListenNPC";
                ["TeleportToId"] = 370009;
                ["TeleportOffsetY"] = 100;
                ["RequiredAnyTextLines"] = {
                    "AchillesFirstMeeting";
                    "AchillesFirstMeeting_Alt";
                };
                ["Partner"] = "NPC_Achilles_01";
                ["UseableOffSource"] = true;
                ["AngleTowardTargetId"] = 370009;
                ["EndVoiceLines"] = {
                    {
                        {
                            ["Cue"] = "/VO/Achilles_0129";
                        };
                        ["PreLineWait"] = 0.55;
                        ["ObjectType"] = "NPC_Achilles_01";
                    };
                    {
                        {
                            ["Cue"] = "/VO/ZagreusHome_0990";
                        };
                        ["PreLineWait"] = 0.15;
                        ["UsePlayerSource"] = true;
                    };
                };
                ["PlayOnce"] = true;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusPostEpilogue01"] = {
                {
                    ["Text"] = "So, I am quite confused, I must admit, my friend. The Queen Persephone, she is your mother, then? How is it that she came to reside, here?";
                    ["Cue"] = "/VO/Orpheus_0269";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Defiant_01";
                    ["Cue"] = "/VO/ZagreusHome_3263";
                    ["PreLineAnim"] = "ZagreusInteractionThoughtful";
                    ["Text"] = "Well, {#DialogueItalicFormat}erm{#PreviousFormat}... it all started when my father saw her on Olympus, and... they fell madly in love. He swept her off her feet, and brought her here. The Olympians, they got pretty worried when they saw she was gone. But now it's OK! Everything's out in the open.";
                };
                {
                    ["Text"] = "But, surely the Queen's mother on Olympus, the great goddess Demeter... surely she would quite like it if she saw her daughter still, from time to time?";
                    ["Cue"] = "/VO/Orpheus_0270";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Oh, that! Thing is, Mother ate some... pomegranate seeds when she was here. And we have rules about that stuff, you know! It means she cannot leave this place for very long at all. I'm sure Demeter will understand. And unfreeze everything when her daughter's around.";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_3264";
                    ["PostLineAnim"] = "ZagreusTalkDenialReturnToIdle";
                    ["PreLineAnim"] = "ZagreusTalkDenialStart";
                };
                {
                    ["Text"] = "Ah, yes, pomegranate seeds, of course, of course! Though, there is one more subject I don't understand, which is... how {#DialogueItalicFormat}you {#PreviousFormat}fit into all of this. Were you not trying to escape from here?";
                    ["Cue"] = "/VO/Orpheus_0271";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Defiant_01";
                    ["Cue"] = "/VO/ZagreusHome_3265";
                    ["PreLineAnim"] = "ZagreusInteractionThoughtful";
                    ["Text"] = "Forget about me, Orpheus! This isn't about me, it's about Mother. What's important is she's here, where she belongs.";
                };
                {
                    ["Text"] = "I see! I understand. Well, thank you, then, for clearing all that up. It is a splendid tale, I must say, and every part of it makes sense to me, at last.";
                    ["Cue"] = "/VO/Orpheus_0272";
                };
                ["RequiredTextLines"] = {
                    "OrpheusGift01";
                    "OlympianReunionQuestComplete";
                };
                ["RequiredFalseFlags"] = {
                    "PersephoneAway";
                };
                ["Name"] = "OrpheusPostEpilogue01";
                ["UseableOffSource"] = true;
                ["PlayOnce"] = true;
                ["EndVoiceLines"] = {
                    {
                        ["Cue"] = "/VO/ZagreusHome_3266";
                    };
                    ["UsePlayerSource"] = true;
                    ["PreLineWait"] = 0.4;
                    ["RequiredMinElapsedTime"] = 2.5;
                };
                ["SuperPriority"] = true;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusAboutEurydice03"] = {
                {
                    ["Text"] = "Pray tell me something, Zagreus. How is she lately, hm? Eurydice, I mean. Her hair, fall colors, or full bloom? Her poise, as proud and supple as the oak?";
                    ["Cue"] = "/VO/Orpheus_0132";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "She's all right, Orpheus. Seems comfortable within her little place in Asphodel. The only thing that seems to bother her at all is... when I mention you. Is there nothing you can do to patch things up?";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Serious_01";
                    ["Cue"] = "/VO/ZagreusHome_1009";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                };
                {
                    ["Text"] = "Alas, I cannot change the past, my friend. So, no. As you can plainly see by now, I'm dead to her. Rightfully so, at that.";
                    ["Cue"] = "/VO/Orpheus_0133";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "But that's just a technicality! I mean, you're here, she's there! So what if you're not breathing anymore, you have all eternity ahead of you. Don't you want to see her again?";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Defiant_01";
                    ["Cue"] = "/VO/ZagreusHome_1010";
                    ["PostLineAnim"] = "ZagreusTalkDenialReturnToIdle";
                    ["PreLineAnim"] = "ZagreusTalkDenialStart";
                };
                {
                    ["Text"] = "Don't I want to see my Eurydice again...? Why, yes. That, more than anything, my friend. Provided she wanted to see me. I tried once to disturb her everlasting rest, as you well know. And that did not pan out as I had hoped....";
                    ["Cue"] = "/VO/Orpheus_0134";
                };
                ["EndWait"] = 0.6;
                ["EndCue"] = "/VO/ZagreusHome_1011";
                ["Name"] = "OrpheusAboutEurydice03";
                ["UseableOffSource"] = true;
                ["PlayOnce"] = true;
                ["Priority"] = true;
                ["RequiredAnyTextLines"] = {
                    "EurydiceAboutOrpheus03";
                    "OrpheusAboutEurydice06";
                };
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusMiscMeeting02"] = {
                {
                    ["Text"] = "It's awfully quiet here, you know, when you're out and about? Makes me a bit self-conscious, truth be told, seeing as ostensibly I'm the musician of this court.";
                    ["Cue"] = "/VO/Orpheus_0067";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Look, if you decide to start strumming on that lyre again, I'm sure nobody here is going to mind. Though you take care, OK?";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_3547";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                };
                ["RequiredAnyTextLines"] = {
                    "OrpheusFirstMeeting";
                    "OrpheusFirstMeeting_Alt";
                };
                ["Name"] = "OrpheusMiscMeeting02";
                ["UseableOffSource"] = true;
                ["RequiredFalseTextLines"] = {
                    "OrpheusSingsAgain01";
                    "OrpheusSingsAgain01_B";
                    "OrpheusSingsAgain01_C";
                    "OrpheusSingsAgain01_D";
                    "OrpheusSingsAgain02";
                    "OrpheusSingsAgain03";
                    "OrpheusSingsAgain03_B";
                };
                ["EndVoiceLines"] = {
                    {
                        ["Cue"] = "/VO/Orpheus_0177";
                    };
                    ["PreLineWait"] = 0.4;
                    ["ObjectType"] = "NPC_Orpheus_01";
                };
                ["PlayOnce"] = true;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusTallTale04"] = {
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Hey Orpheus, you've noticed the resemblance between me and Dionysus, haven't you, mate? I'll tell you a little secret but you have to promise not to tell... We're really the same god. I love a good feast, don't I?";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_0215";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                };
                {
                    ["Text"] = "But, Zagreus, that is a striking revelation, the connection you describe. I see it! I can see it now! To think the god of wine and you are intricately linked, it isn't obvious, is it?";
                    ["Cue"] = "/VO/Orpheus_0082";
                    ["Emote"] = "PortraitEmoteSurprise";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Oh, there's more to it! A bit grim, really, as I'm a little older than I look. You see, the Titans, they once tore me limb from limb, but then my heart was saved, and that's where Dionysus comes from! That is the connection between us, you understand me, mate?";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_0216";
                    ["PostLineAnim"] = "ZagreusTalkDenialReturnToIdle";
                    ["PreLineAnim"] = "ZagreusTalkDenialStart";
                };
                {
                    ["Text"] = "Your tale stirs my soul, it truly does, my friend. It is a marvel to me that such heroism isn't widely known, and I'm committed to the spread of all such truths.";
                    ["Cue"] = "/VO/Orpheus_0083";
                    ["PreLineAnim"] = "OrpheusFidget";
                };
                ["EndWait"] = 0.5;
                ["EndCue"] = "/VO/ZagreusHome_0725";
                ["Name"] = "OrpheusTallTale04";
                ["UseableOffSource"] = true;
                ["RequiredTextLines"] = {
                    "OrpheusTallTale03";
                    "DionysusAboutOrpheus01";
                };
                ["Priority"] = true;
                ["PlayOnce"] = true;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusMusicProgress04"] = {
                {
                    ["Text"] = "I must commend you on the most splendid lyre-playing emanating from your bedchambers, my friend. It seems we have a second court musician, now.";
                    ["Cue"] = "/VO/Orpheus_0221";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Thank you for encouraging me to give it a shot, mate. And for the kind words.";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_1047";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                };
                ["RequiredMinItemInteractions"] = {
                    ["HouseLyre01"] = 210;
                };
                ["RequiredTextLines"] = {
                    "OrpheusMusicProgress03";
                };
                ["RequiredCosmetics"] = {
                    "HouseLyre01";
                };
                ["UseableOffSource"] = true;
                ["RequiredFalseTextLinesLastRun"] = {
                    "OrpheusMusicProgress03";
                };
                ["PlayOnce"] = true;
                ["Name"] = "OrpheusMusicProgress04";
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusAboutSingersReunionQuest01"] = {
                {
                    ["Text"] = "Zagreus! The most amazing circumstances have occurred. The terms of my employment, they've been altered such that... I may visit Asphodel sometimes. May visit {#DialogueItalicFormat}her{#PreviousFormat}.";
                    ["Cue"] = "/VO/Orpheus_0142";
                    ["Emote"] = "PortraitEmoteSurprise";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "That's great! Orpheus, what are you waiting for, mate? Go and find your muse out there! You two have lots to catch up on, I think.";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_1022";
                    ["PostLineAnim"] = "ZagreusTalkDenialReturnToIdle";
                    ["PreLineAnim"] = "ZagreusTalkDenialStart";
                };
                {
                    ["Text"] = "I think you're right. I am so very anxious, I must say. But I must also thank you, for this opportunity, and... for speaking with me all this time. So, how might I repay you?";
                    ["Cue"] = "/VO/Orpheus_0143";
                };
                {
                    ["PreLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_1023";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["Text"] = "Why is it always talk of payment around here? You're my mate. And your songs have lifted many spirits here, including mine. Now go, and make the most of this, will you?";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                    ["PostLineAnimTarget"] = "Hero";
                    ["PostLineFunctionArgs"] = {
                        ["AnimationState"] = "NPCOrpheusExited";
                        ["WaitTime"] = 3.5;
                    };
                    ["Speaker"] = "CharProtag";
                    ["PostLineThreadedFunctionName"] = "OrpheusExit";
                    ["SetFlagTrue"] = "OrpheusReunionInProgress";
                };
                ["GiftableOffSource"] = true;
                ["Name"] = "OrpheusAboutSingersReunionQuest01";
                ["SuperPriority"] = true;
                ["OnQueuedFunctionArgs"] = {
                    ["VoiceLines"] = {
                        {
                            ["PreLineAnim"] = "OrpheusFidget";
                            ["Cue"] = "/VO/Orpheus_0235";
                        };
                        ["Cooldowns"] = {
                            {
                                ["Time"] = 10;
                                ["Name"] = "HouseNPCAnySpeech";
                            };
                        };
                    };
                    ["WithinDistance"] = 500;
                };
                ["OnQueuedFunctionName"] = "CheckDistanceTriggerThread";
                ["RequiresNullAmbientMusicId"] = true;
                ["UseableOffSource"] = true;
                ["PlayOnce"] = true;
                ["EndVoiceLines"] = {
                    {
                        ["Cue"] = "/VO/Orpheus_0144";
                    };
                    ["PreLineWait"] = 0.55;
                };
                ["RequiredCosmetics"] = {
                    "OrpheusEurydiceQuestItem";
                };
                ["StatusAnimation"] = "StatusIconWantsToTalkImportant";
            };
            ["OrpheusWithHades01"] = {
                {
                    ["Text"] = "...You called upon your humble court musician, as I understand, Lord Hades sir? Referring to myself of course?";
                    ["Cue"] = "/VO/Orpheus_0096";
                    ["PreLineWait"] = 0.3;
                };
                {
                    ["Speaker"] = "NPC_Hades_01";
                    ["Portrait"] = "Portrait_Hades_Default_01";
                    ["Cue"] = "/VO/Hades_0281";
                    ["Text"] = "Well, Orpheus... if you're quite finished with your little stint within the depths of Tartarus, I'd like to ask again: Play us a song, already. Or else next time I'll not be quite so charitable with your punishment.";
                    ["PreLineWait"] = 0.35;
                };
                {
                    ["Text"] = "Oh, that. I must apologize, again, Lord Hades sir. For I'm afraid that I've no wish to sing as yet. In spite of your persuasiveness even. And, that, um, is my final word upon the subject. At this time.";
                    ["Cue"] = "/VO/Orpheus_0097";
                };
                {
                    ["Portrait"] = "Portrait_Hades_Default_01";
                    ["Cue"] = "/VO/Hades_0282";
                    ["Speaker"] = "NPC_Hades_01";
                    ["Text"] = "Is that so...? Why, then, I'll go ahead and wait. I've all the patience in the world.";
                };
                ["RequiredFalseTextLines"] = {
                    "OrpheusSingsAgain01";
                    "OrpheusSingsAgain01_B";
                    "OrpheusSingsAgain01_C";
                    "OrpheusSingsAgain01_D";
                    "OrpheusSingsAgain02";
                    "OrpheusSingsAgain03";
                    "OrpheusSingsAgain03_B";
                };
                ["TeleportToId"] = 393481;
                ["EndWait"] = 0.6;
                ["UseableOffSource"] = true;
                ["AngleTowardTargetId"] = 370006;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
                ["GiftableOffSource"] = true;
                ["Name"] = "OrpheusWithHades01";
                ["TeleportOffsetX"] = 80;
                ["InteractDistance"] = 400;
                ["UseText"] = "UseListenNPC";
                ["TeleportOffsetY"] = -80;
                ["EndCue"] = "/VO/ZagreusHome_0553";
                ["Partner"] = "NPC_Hades_01";
                ["IsIdAlive"] = 370006;
                ["PlayOnce"] = true;
                ["Priority"] = true;
                ["BlockDistanceTriggers"] = true;
                ["RequiredAnyTextLines"] = {
                    "OrpheusFirstMeeting";
                    "OrpheusFirstMeeting_Alt";
                };
            };
            ["OrpheusSingsAgain01_B"] = {
                {
                    ["Text"] = "I've decided I should give this singing thing another shot for now, my friend. I hope you like it.";
                    ["Cue"] = "/VO/Orpheus_0088";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                    ["PreLineAnimTarget"] = "Hero";
                };
                {
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_1027";
                    ["Speaker"] = "CharProtag";
                    ["Text"] = "This is amazing, mate. You sing quite beautifully, with or without your muse.";
                };
                {
                    ["Text"] = "How kind of you. It's just... seeing you carry on like this, time after time, I was reminded that I might as well get on with my existence, too. Such as it is right now.";
                    ["Cue"] = "/VO/Orpheus_0230";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PostLineAnimTarget"] = "Hero";
                };
                ["GiftableOffSource"] = true;
                ["Name"] = "OrpheusSingsAgain01_B";
                ["RequiredTextLines"] = {
                    "OrpheusMiscMeeting07";
                    "OrpheusGift05";
                };
                ["RequiredFalseTextLines"] = {
                    "OrpheusSingsAgain01";
                    "OrpheusSingsAgain01_C";
                    "OrpheusSingsAgain01_D";
                };
                ["OnQueuedFunctionArgs"] = {
                    ["Restore"] = true;
                    ["TrackName"] = "/Music/OrpheusSong1VACOUSTIC";
                };
                ["RequiredAmbientTrackNameMatch"] = true;
                ["InitialGiftableOffSource"] = true;
                ["PlayOnce"] = true;
                ["UseableOffSource"] = true;
                ["RequiredAnyTextLines"] = {
                    "EurydiceFirstMeeting01_A";
                    "EurydiceFirstMeeting01_B";
                    "EurydiceFirstMeeting01_C";
                };
                ["OnQueuedFunctionName"] = "MusicianMusic";
                ["RequiredFalseQueuedTextLines"] = {
                    "OlympianReunionQuestComplete";
                };
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusTallTale07"] = {
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Hey, Orpheus? I figure that you've heard by now about how I bested the Minotaur Asterius, alongside Theseus, the Champion of Elysium, himself? I don't think I even broke a sweat.";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_1050";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                };
                {
                    ["Text"] = "I scarce can possibly imagine such a spectacle, my friend! But certainly I shall attempt to try!";
                    ["Cue"] = "/VO/Orpheus_0223";
                    ["PreLineAnim"] = "OrpheusFidget";
                };
                ["Name"] = "OrpheusTallTale07";
                ["EndCue"] = "/VO/ZagreusHome_1051";
                ["EndWait"] = 0.6;
                ["UseableOffSource"] = true;
                ["RequiredRoomThisRun"] = "D_Intro";
                ["RequiredTextLines"] = {
                    "OrpheusTallTale03";
                };
                ["PlayOnce"] = true;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusAboutDistantMemory01"] = {
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Hey, Orpheus. The keepsake that you gave me... it's come in useful, thanks. I can't quite see what's in the container, though. I shouldn't open it, should I?";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_1030";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                };
                {
                    ["Text"] = "No, Zagreus. Unless of course you wanted to set loose a cherished living memory of mine, and take from me that fleeting bit of joy?";
                    ["Cue"] = "/VO/Orpheus_0154";
                    ["PreLineAnim"] = "OrpheusFidget";
                };
                ["EndCue"] = "/VO/ZagreusHome_1031";
                ["Name"] = "OrpheusAboutDistantMemory01";
                ["UseableOffSource"] = true;
                ["EndWait"] = 0.6;
                ["PlayOnce"] = true;
                ["RequiredKeepsake"] = "DistanceDamageTrait";
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusTallTale05"] = {
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_0217";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                    ["Text"] = "Hey Orpheus, you know I've just been messing with you, with those Dionysus tales, and all that? Just trying to liven things up for us, mate.";
                };
                {
                    ["Text"] = "Oh, Zagreus! There isn't need for such humility, not when one's deeds of heroism are as great and numerous as yours! It is an honor to have heard such deeds first-hand!";
                    ["Cue"] = "/VO/Orpheus_0084";
                    ["PreLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PreLineAnimTarget"] = "Hero";
                };
                ["EndCue"] = "/VO/ZagreusHome_0726";
                ["Name"] = "OrpheusTallTale05";
                ["UseableOffSource"] = true;
                ["PlayOnce"] = true;
                ["RequiredTextLines"] = {
                    "OrpheusTallTale04";
                };
                ["EndWait"] = 0.5;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusWithPersephone01"] = {
                {
                    ["Speaker"] = "NPC_Persephone_Home_01";
                    ["PreLineWait"] = 0.35;
                    ["PreLineAnimTarget"] = 555714;
                    ["Portrait"] = "Portrait_Persephone_Queen_01";
                    ["Cue"] = "/VO/Persephone_0197";
                    ["PreLineAnim"] = "PersephoneUnderworld_Vulnerable";
                    ["Text"] = "...{#DialogueItalicFormat}Ah{#PreviousFormat}, but to think that our esteemed musician of the court is none other than {#DialogueItalicFormat}you{#PreviousFormat}, Orpheus! In matters of music, at least, Hades and I have similar tastes. Anyway, I don't mean to keep you!";
                };
                {
                    ["Text"] = "I shall be honored to perform my songs, Your Grace. And, might I add, Your Grace bears many of the striking features of your son? I understand now where he gets his charm.";
                    ["Cue"] = "/VO/Orpheus_0268";
                    ["PreLineAnim"] = "OrpheusFidget";
                    ["PreLineWait"] = 0.35;
                };
                ["TeleportToId"] = 555714;
                ["MaxRunsSinceAnyTextLines"] = {
                    ["TextLines"] = {
                        "Ending01";
                    };
                    ["Count"] = 25;
                };
                ["UseableOffSource"] = true;
                ["AngleTowardTargetId"] = 555714;
                ["EndVoiceLines"] = {
                    {
                        ["PreLineAnim"] = "PersephoneUnderworld_Greeting";
