            };
            ["OrpheusMiscMeeting05"] = {
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Anything I can do to help you find your muse, mate?";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_0205";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                };
                {
                    ["Text"] = "I fear my muse is long since lost to me, my friend, though truly thanks for asking. I suppose she must be out there somewhere still, since I once traveled 'cross this land in search of her, and found her then. But that was quite a while back.";
                    ["Cue"] = "/VO/Orpheus_0072";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Defiant_01";
                    ["Cue"] = "/VO/ZagreusHome_0206";
                    ["PreLineAnim"] = "ZagreusTalkDenial_Full";
                    ["Text"] = "Wait, you found her? What happened?";
                };
                {
                    ["Text"] = "Well, this was back when I was still alive, you understand. Your father, why, he doesn't care for anyone to leave this realm, and, basically now I'm stuck here as well! Not seen her since, and, I'm not much for travel anymore.";
                    ["Cue"] = "/VO/Orpheus_0073";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Empathetic_01";
                    ["Cue"] = "/VO/ZagreusHome_1859";
                    ["PreLineAnim"] = "ZagreusInteractionThoughtful";
                    ["Text"] = "That's... I'm sorry to hear that. Thank you for letting me know. I hope you get to see her again someday.";
                };
                {
                    ["Text"] = "I appreciate the sentiment, my friend, though please don't worry about her or me. I mean, we're dead! We're fine.";
                    ["Cue"] = "/VO/Orpheus_0074";
                    ["PreLineAnim"] = "OrpheusFidget";
                };
                ["Name"] = "OrpheusMiscMeeting05";
                ["UseableOffSource"] = true;
                ["RequiredFalseTextLines"] = {
                    "EurydiceMentionsOrpheus01";
                    "EurydiceFirstMeeting01_C";
                    "EurydiceAboutOrpheus01";
                };
                ["RequiredTextLines"] = {
                    "OrpheusMiscMeeting04";
                };
                ["PlayOnce"] = true;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusAboutEurydice06Extra"] = {
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Orpheus, you said that it was one of life's injustices that Eurydice doesn't get her fair share of the credit for the songs she wrote. Isn't there something we can do?";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Empathetic_01";
                    ["Cue"] = "/VO/ZagreusHome_2622";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                };
                {
                    ["Text"] = "Why, I don't know, my friend. Once people set their minds to certain things... it can be difficult to show them other possibilities exist. What's to be done?";
                    ["Cue"] = "/VO/Orpheus_0247";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "I don't know... tell them they're wrong? Politely, perhaps not? Or... tell them what's right. Get the word out about what's right? Can't we do that?";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Defiant_01";
                    ["Cue"] = "/VO/ZagreusHome_2623";
                    ["PostLineAnim"] = "ZagreusTalkDenialReturnToIdle";
                    ["PreLineAnim"] = "ZagreusTalkDenialStart";
                };
                {
                    ["Text"] = "Get the word out...? But I am court musician of this House. My songs no longer reach too many ears. Although... I do suppose all of these shades about... they are my audience, as well. I shall make certain that they know whose songs I sing.";
                    ["Cue"] = "/VO/Orpheus_0248";
                };
                ["Name"] = "OrpheusAboutEurydice06Extra";
                ["UseableOffSource"] = true;
                ["PlayOnce"] = true;
                ["EndVoiceLines"] = {
                    {
                        ["Cue"] = "/VO/ZagreusHome_2624";
                    };
                    ["PreLineWait"] = 0.4;
                    ["UsePlayerSource"] = true;
                };
                ["RequiredTextLines"] = {
                    "OrpheusAboutEurydice06";
                };
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusAboutSinging01"] = {
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "I always meant to ask you, Orpheus. Where did you learn to sing like that? Was it really Apollo himself who taught you?";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_1039";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                };
                {
                    ["Text"] = "{#DialogueItalicFormat}Oh{#PreviousFormat}, why, I learned from many different sources, Zagreus. That is before all of my inspiration started coming from a single source. I credit my accomplishments to her, and to Apollo, and the gods. And to considerable time spent practicing!";
                    ["Cue"] = "/VO/Orpheus_0212";
                    ["PreLineAnim"] = "OrpheusFidget";
                };
                ["EndCue"] = "/VO/ZagreusHome_1040";
                ["Name"] = "OrpheusAboutSinging01";
                ["UseableOffSource"] = true;
                ["RequiredAnyTextLines"] = {
                    "OrpheusSingsAgain01";
                    "OrpheusSingsAgain01_B";
                    "OrpheusSingsAgain01_C";
                    "OrpheusSingsAgain01_D";
                    "OrpheusSingsAgain03";
                    "OrpheusSingsAgain03_B";
                };
                ["PlayOnce"] = true;
                ["EndWait"] = 0.4;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusSingsAgain02"] = {
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_0730";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                    ["Text"] = "Orpheus, sorry to interrupt, it's just... I couldn't help but notice that new ballad that you're playing, there.";
                };
                {
                    ["Text"] = "Technically, one ought consider it a hymn, my friend! In honor of your numerous travails, prior to your current set of circumstances, which must pale in comparison to all the rigors you've endured to date!";
                    ["Cue"] = "/VO/Orpheus_0099";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Empathetic_01";
                    ["Cue"] = "/VO/ZagreusHome_0731";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["Text"] = "{#DialogueItalicFormat}Erm{#PreviousFormat}, the thing is... none of the information in your hymn is accurate. It's nonsense. I was just kidding with you, mate! I tried to make that clear. You get so lively when I tell you my tall tales, you know? You're not angry with me, are you...?";
                };
                {
                    ["Text"] = "Heavens, no, my friend! Your humility is matched only by your perseverance in the face of adversity! May your great deeds live on forever, much like you!";
                    ["Cue"] = "/VO/Orpheus_0100";
                    ["PreLineAnim"] = "OrpheusFidget";
                    ["Emote"] = "PortraitEmoteSurprise";
                };
                ["GiftableOffSource"] = true;
                ["Name"] = "OrpheusSingsAgain02";
                ["RequiredTextLines"] = {
                    "OrpheusTallTale05";
                    "OrpheusTallTale06";
                };
                ["OnQueuedFunctionArgs"] = {
                    ["Restore"] = true;
                    ["TrackName"] = "/Music/OrpheusSong2";
                };
                ["RequiredAmbientTrackNameMatch"] = true;
                ["EndCue"] = "/VO/ZagreusHome_0732";
                ["EndWait"] = 0.6;
                ["UseableOffSource"] = true;
                ["PlayOnce"] = true;
                ["OnQueuedFunctionName"] = "MusicianMusic";
                ["RequiredFalseQueuedTextLines"] = {
                    "OlympianReunionQuestComplete";
                };
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusAboutHermes01"] = {
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Oh, Orpheus? I heard from Hermes, messenger and god of travel, and all that? It's odd {#DialogueItalicFormat}I'm {#PreviousFormat}giving you his message in this case, but he says hey! Admires your musical ability, as well.";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_2616";
                    ["PostLineAnim"] = "ZagreusTalkDenialReturnToIdle";
                    ["PreLineAnim"] = "ZagreusTalkDenialStart";
                };
                {
                    ["Text"] = "{#DialogueItalicFormat}Oh{#PreviousFormat}, that was kind of him, my friend! When I first ventured deep into this realm, whilst searching for the soul of my lost muse... after I failed utterly, it was Lord Hermes who whisked her away. It happened so fast. He did an {#DialogueItalicFormat}excellent {#PreviousFormat}job!";
                    ["Cue"] = "/VO/Orpheus_0229";
                };
                ["EndCue"] = "/VO/ZagreusHome_2617";
                ["Name"] = "OrpheusAboutHermes01";
                ["UseableOffSource"] = true;
                ["PlayOnce"] = true;
                ["RequiredTextLines"] = {
                    "HermesAboutOrpheus01";
                    "OrpheusGift02";
                };
                ["EndWait"] = 0.4;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusAboutDistantMemory02"] = {
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Orpheus, the Distant Memory you gave me... it's a bit of your past with Eurydice in there, isn't it. I'm grateful, but... why give me such a precious gift as that?";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_1032";
                    ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                    ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                };
                {
                    ["Text"] = "I'm glad you like it, Zagreus. Some memories are cherished, yes, indeed. But there can come a point where they provide more benefit to others than ourselves. Don't you agree?";
                    ["Cue"] = "/VO/Orpheus_0155";
                };
                ["Name"] = "OrpheusAboutDistantMemory02";
                ["RequiredTextLines"] = {
                    "OrpheusAboutDistantMemory01";
                    "OrpheusAboutEurydice03";
                };
                ["RequiredKeepsake"] = "DistanceDamageTrait";
                ["EndCue"] = "/VO/ZagreusHome_1033";
                ["EndWait"] = 0.6;
                ["UseableOffSource"] = true;
                ["RequiresMaxKeepsake"] = true;
                ["PlayOnce"] = true;
                ["RequiredAnyTextLines"] = {
                    "OrpheusGift05";
                    "OrpheusAboutEurydice02";
                    "OrpheusAboutEurydice02_B";
                };
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusWithAchilles01"] = {
                {
                    ["Text"] = "...You're much too modest, Lord Achilles, for someone with such a number of heroic deeds and glorious decapitations to his name! You ought to be more like ever-boastful Zagreus, and talk it up some more!";
                    ["Cue"] = "/VO/Orpheus_0090";
                    ["PreLineWait"] = 0.3;
                };
                {
                    ["Portrait"] = "Portrait_MaleGhost_Default_01";
                    ["Cue"] = "/VO/Achilles_0080";
                    ["Speaker"] = "NPC_Achilles_01";
                    ["Text"] = "Oh, fear not, Orpheus, I was quite boastful in my day. And would you look at where it got me? Besides, I've not the imagination to come up with tales as tall as those of our Prince Zagreus.";
                };
                ["GiftableOffSource"] = true;
                ["RequiredAnyTextLines"] = {
                    "OrpheusFirstMeeting";
                    "OrpheusFirstMeeting_Alt";
                };
                ["Name"] = "OrpheusWithAchilles01";
                ["RequiredAnyOtherTextLines"] = {
                    "AchillesFirstMeeting";
                    "AchillesFirstMeeting_Alt";
                };
                ["TeleportOffsetX"] = 40;
                ["RequiredTextLines"] = {
                    "AchillesGrantsCodex";
                };
                ["UseText"] = "UseListenNPC";
                ["TeleportToId"] = 370009;
                ["TeleportOffsetY"] = 100;
                ["EndCue"] = "/VO/ZagreusHome_0258";
                ["EndWait"] = 0.4;
                ["UseableOffSource"] = true;
                ["AngleTowardTargetId"] = 370009;
                ["Partner"] = "NPC_Achilles_01";
                ["PlayOnce"] = true;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusTallTale02"] = {
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Hey Orpheus? You know about the time I vanquished seven legions of Bloodless warriors with both hands tied behind my back while hopping on one foot? Lord Poseidon dared me to do it, you know.";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_0213";
                    ["PostLineAnim"] = "ZagreusTalkDenialReturnToIdle";
                    ["PreLineAnim"] = "ZagreusTalkDenialStart";
                };
                {
                    ["Text"] = "Why, that is a spectacularly vivid tale, Zagreus, and most deserving to be chronicled in song! Would that there were a poet here still willing to commit such deeds to verse.";
                    ["Cue"] = "/VO/Orpheus_0080";
                    ["PreLineAnim"] = "OrpheusFidget";
                    ["Emote"] = "PortraitEmoteSurprise";
                };
                ["EndCue"] = "/VO/ZagreusHome_0723";
                ["Name"] = "OrpheusTallTale02";
                ["UseableOffSource"] = true;
                ["PlayOnce"] = true;
                ["RequiredTextLines"] = {
                    "OrpheusTallTale01";
                };
                ["EndWait"] = 0.45;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusMiscMeeting03"] = {
                {
                    ["Text"] = "Oh, hello Zagreus. You look a little down. And so I was just wondering, would you perchance fancy a song right now?";
                    ["Cue"] = "/VO/Orpheus_0068";
                };
                {
                    ["Text"] = "Orpheus_OfferText01";
                    ["Choices"] = {
                        {
                            {
                                ["Speaker"] = "CharProtag";
                                ["PreLineAnimTarget"] = "Hero";
                                ["Text"] = "How about {#DialogueItalicFormat}The Lament{#PreviousFormat}? You used to play that one a lot!";
                                ["PostLineAnimTarget"] = "Hero";
                                ["Portrait"] = "Portrait_Zag_Default_01";
                                ["Cue"] = "/VO/ZagreusHome_3548";
                                ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                                ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                            };
                            {
                                ["Text"] = "Oh, fancy that one do you? Alas, I've not the heart to sing it anymore. I'm glad you like it, though.";
                                ["Cue"] = "/VO/Orpheus_0069";
                            };
                            ["ChoiceText"] = "OrpheusJukebox_00";
                        };
                        {
                            {
                                ["Speaker"] = "CharProtag";
                                ["PreLineAnimTarget"] = "Hero";
                                ["Text"] = "How about {#DialogueItalicFormat}In the Blood{#PreviousFormat}? That's one of your old hits, right?";
                                ["PostLineAnimTarget"] = "Hero";
                                ["Portrait"] = "Portrait_Zag_Default_01";
                                ["Cue"] = "/VO/ZagreusHome_3549";
                                ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                                ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                            };
                            {
                                ["Text"] = "Oh, fancy that one do you? Alas, I've not the heart to sing it anymore. I'm glad you like it, though.";
                                ["Cue"] = "/VO/Orpheus_0069";
                            };
                            ["ChoiceText"] = "OrpheusJukebox_01";
                        };
                        {
                            {
                                ["Speaker"] = "CharProtag";
                                ["PreLineAnimTarget"] = "Hero";
                                ["Text"] = "How about {#DialogueItalicFormat}Argonauts{#PreviousFormat}, didn't you sail with them?";
                                ["PostLineAnimTarget"] = "Hero";
                                ["Portrait"] = "Portrait_Zag_Default_01";
                                ["Cue"] = "/VO/ZagreusHome_3550";
                                ["PostLineAnim"] = "ZagreusTalkEmpathy_Return";
                                ["PreLineAnim"] = "ZagreusTalkEmpathyStart";
                            };
                            {
                                ["Text"] = "Oh, fancy that one do you? Alas, I've not the heart to sing it anymore. I'm glad you like it, though.";
                                ["Cue"] = "/VO/Orpheus_0069";
                            };
                            ["ChoiceText"] = "OrpheusJukebox_02";
                        };
                    };
                };
                ["RequiredAnyTextLines"] = {
                    "OrpheusFirstMeeting";
                    "OrpheusFirstMeeting_Alt";
                };
                ["Name"] = "OrpheusMiscMeeting03";
                ["UseableOffSource"] = true;
                ["RequiredFalseTextLines"] = {
                    "OrpheusSingsAgain01";
                    "OrpheusSingsAgain01_B";
                    "OrpheusSingsAgain01_C";
                    "OrpheusSingsAgain01_D";
                    "OrpheusSingsAgain02";
                    "OrpheusSingsAgain03";
                    "OrpheusSingsAgain03_B";
                };
                ["PlayOnce"] = true;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusFirstMeeting"] = {
                {
                    ["Text"] = "Oh, hello, Zagreus. I understand you liberated me from my eternal punishment. And so I have returned to serve your father here. Thanks.";
                    ["Cue"] = "/VO/Orpheus_0186";
                    ["PreLineAnim"] = "OrpheusFidget";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Orpheus, you're back! Look, don't get on Father's bad side like that and you're going to be fine. Besides... right now I think he's angrier with me.";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_1034";
                    ["PostLineAnim"] = "ZagreusTalkDenialReturnToIdle";
                    ["PreLineAnim"] = "ZagreusTalkDenialStart";
                };
                {
                    ["Text"] = "I grieve for you, my friend. But if you've come to ask me for a song, why, I'm afraid I must stand firm about my answer.";
                    ["PostLineFunctionArgs"] = {
                        ["Text"] = "OrpheusUnlockItem";
                        ["AnimationOutName"] = "LocationTextBGOut";
                        ["Title"] = "MainSubPlotComplete";
                        ["AnimationName"] = "LocationTextBG";
                        ["Delay"] = 2.5;
                        ["TextRevealSound"] = "/Leftovers/Menu Sounds/TextReveal3";
                    };
                    ["Cue"] = "/VO/Orpheus_0187";
                    ["PostLineThreadedFunctionName"] = "MaxedRelationshipPresentation";
                    ["PreLineAnim"] = "OrpheusFidget";
                };
                ["PlayOnce"] = true;
                ["EndCue"] = "/VO/ZagreusHome_1035";
                ["Name"] = "OrpheusFirstMeeting";
                ["UseableOffSource"] = true;
                ["RequiredFalseTextLines"] = {
                    "Ending01";
                    "OrpheusFirstMeeting_Alt";
                };
                ["Priority"] = true;
                ["EndWait"] = 0.4;
                ["StatusAnimation"] = "StatusIconWantsToTalk";
            };
            ["OrpheusFirstMeeting_Alt"] = {
                {
                    ["Text"] = "Oh, hello, Zagreus. I understand you liberated me from my eternal punishment. And so I have returned to serve your father here. Thanks.";
                    ["Cue"] = "/VO/Orpheus_0186";
                    ["PreLineAnim"] = "OrpheusFidget";
                };
                {
                    ["Speaker"] = "CharProtag";
                    ["PreLineAnimTarget"] = "Hero";
                    ["Text"] = "Orpheus, you're back! Look, don't get on Father's bad side like that, and you're going to be fine. I've fought with him enough for all our sakes.";
                    ["PostLineAnimTarget"] = "Hero";
                    ["Portrait"] = "Portrait_Zag_Default_01";
                    ["Cue"] = "/VO/ZagreusHome_3572";
                    ["PostLineAnim"] = "ZagreusTalkDenialReturnToIdle";
                    ["PreLineAnim"] = "ZagreusTalkDenialStart";
                };
                {
                    ["Text"] = "I grieve for you, my friend. But if you've come to ask me for a song, why, I'm afraid I must stand firm about my answer.";
                    ["PostLineFunctionArgs"] = {
                        ["Text"] = "OrpheusUnlockItem";
