        ["UseText"] = "UseTalkToMusician";
        ["NextInteractLines"] = {
            {
                ["Text"] = "This hymn is dedicated to your deeds, my friend!";
                ["Cue"] = "/VO/Orpheus_0104";
            };
            ["GiftableOffSource"] = true;
            ["Name"] = "OrpheusSingingChat04";
            ["RequiredTextLines"] = {
